 def test_functional_layout_and_source_variants(self):
  self.assertEqual(set(self.by),set(self.r['preserved_functional_break_ids']));self.assertFalse(any('line_break_policy' in e for e in self.p['entries']))
  for symbol,count in [('\\n', 144), ('(', 53), (')', 53), ('~', 23)]:self.assertEqual(sum(t.count(symbol) for t in self.ts),count)
  for i,t in {'coalesced:f5e1c7eecc7fb26f374e65e91483effc5fd98d41639ee1ffb46903786a12048f': '在洁菲回来之前，\\n先在住处等着吧。', 'coalesced:6662068bb12735f752b6f60c9c5d19d15e232aa4e70077aea931d44e6463e2c7': '必须救朱特。\\n去海底洞窟寻找强大的卡蒙德。 ', 'coalesced:198636995e99a13ba5303c0ecf12aab96a920551d08ca1eac64b7406e2f15fab': '去杜南丘陵时，\\n可以搭乘南部军的卡尔玛。 ', 'coalesced:b3e8c5ce88c7611e572a0ae4b897f08c5298d6f29fcd043d54b073c82e29febc': '从杜南平原往东北走，\\n就能到鲁哈尔特。', 'coalesced:aff6ff7b83e257ebd1c91fb9c7ac45c1a9f6d1495158039b310fb3a757188171': '火之KAN一出现就用掉，\\n让KAN地雷失效吧。', 'coalesced:2df2f8a3879ff3599f27a62d24b5640d2066bbf24a2f4865f447f73e0f6cb4e1': 'KAN地雷交给露姐姐，\\n鲁哈尔特的北部军就交给我吧！', 'coalesced:86a718f413d6b9d937b6f4d095205667596c227907420e8e1245b9fea21ebbc5': '(南部军驻扎在这里。\\n避免不必要的战斗吧。)', 'coalesced:44f1392f6884adc8adb6915d4ecad2bdd855ad59ebdf728661cc717a770ec818': '(北部军应该已经\\n把手伸进村里了。)', 'coalesced:967e557a07c5aa32e61de197021c7cd18c30b70c577444b8741f2109b6ac4510': '(黑刃要塞里有很多南部军。)', 'coalesced:d486a50c432959b85b0653dd6ab281f70d8c01a193749d25cacae57470d8ce9b': '(看来还去不了高原。\\n爸爸的坟墓也在那里)', 'coalesced:c1d811a807a2c932ebb02fec517b2894b8ee97f55a8ea20cc9e3ce62da751bf8': '最后关头了，大家加把劲。', 'coalesced:5f8db21bdc224f9e909afbd65c47774bc28df93442cbb1a7321ce9bfd915527c': '红莲水晶 ', 'coalesced:8d0f5b9b0ed31f22aec2f2d6d5d23f150ec4ebc2e13c3988997bbb9256f98739': '用于打破水之祭坛结界的媒介', 'coalesced:257fe90fd7d43ede656f03245ca2c4f65442d35444f31bf5a84f4cfe45f33273': '破戒卷轴 ', 'coalesced:b4a11157ed7537053a34517bfc8aa5cdef1b4633bf98cf3c3f4136eafe733bb8': '用于打破火之祭坛结界的媒介', 'coalesced:9e0f28f6cd12c97c5f34e6dd4ceaa40269d92ecc9dacc3671dc36ffac9605d0a': '北部军的库布', 'coalesced:058812d5461aafb3d5f5d1c50062d9f35d2520dbd20a4bdd891d0f320d6af837': '控制室通行卡', 'coalesced:9e54387b635f0360f0fea390587d0c026bca1c20a7d243a438706d4bed226bde': '南部军总司令的信函 '}.items():self.assertEqual(self.by[i],t)
  self.assertNotIn('阿巴杰特',''.join(self.ts));self.assertNotIn('最后一战',''.join(self.ts));self.assertNotIn('破界卷轴',self.ts)
 def test_ending_states_keep_independent_ids(self):
  pairs=[('coalesced:2128d3543c713a98025c68154443c7e8d3bc92126abdcf3e3ea888dd2fa87ed4', 'coalesced:98bf07351fb5e987ff2cb5c2b11b347bc1e09d75006c1b9bbc41482232836015'), ('coalesced:88f0cbcb74523831e05b4def5b252769bf050c64c970430012ce38beb6dcb685', 'coalesced:0e86d8f591ab86dfc7295e59ab2a2855998323fe6ea17ad82e245e6136c90cfc'), ('coalesced:448b8c1ecaa829ffde7286181a6d299838ca49853c495e020ac38b710088eade', 'coalesced:e4382aee7308cd6287169791ae3f344319747cbc3d686a4c23e1b385d35c86ac'), ('coalesced:c8e4d232a8693d685fcef921b9b0b3acd057cd2268802addf2287cec9e9abc94', 'coalesced:6ae06ff5ab35d06ebdfed979ef3d340ea5fc0e33986d2ca44d7bd186fbdcb9f5'), ('coalesced:01a8bdc40bc4c52ec66e0557d62b92f4147cca5650d3d2c2988723955b843b83', 'coalesced:8496d4155e0b7b34133d46e283eab421d23d81f498928121503625ee763a7c6a'), ('coalesced:4add2f06bb8a882c16f67918faf6e203b0fa88429b086eab35ac49c9b19a50c5', 'coalesced:3caf66d1d36e9ab77d90c87522decae9512b168ace825f5bb90b3f72707d27fb')]
  for x,y in pairs[:5]:self.assertNotEqual(x,y);self.assertEqual(self.by[x],self.by[y])
  x,y=pairs[5];self.assertNotEqual(x,y);self.assertNotEqual(self.by[x],self.by[y]);self.assertIn('阿尔戈哥哥',self.by[x]);self.assertIn('阿尔戈哥哥',self.by[y])
 def test_candidate_append(self):
  new=load('locales/zh-Hans/terms.json')['terms'][1073:1084];self.assertEqual(len(new),11);self.assertTrue(all(e['review_status']=='candidate' and e['relation']=='unverified' for e in new));by={e['source']:e['target'] for e in new}
  self.assertEqual(by['홍련의 수정'],'红莲水晶');self.assertEqual(by['파계의 두루마리'],'破戒卷轴');self.assertEqual(by['북부군의 큐브'],'北部军的库布')
 def test_workflow_locks_and_subtitles(self):
  for e in load('locales/zh-Hans/translation-workflow.json')['batches'][110].values():self.assertEqual(hashlib.sha256((R/e['path']).read_bytes()).hexdigest(),e['sha256'])
  plans=load('locales/zh-Hans/subtitle-profile.json')['plans'];self.assertEqual(len(plans),44);self.assertEqual(sum(len(load(e['path'])['entries']) for e in plans),315)
  for e in plans:self.assertEqual(hashlib.sha256((R/e['path']).read_bytes()).hexdigest(),e['sha256'])
